export interface TrustScoreResult {
  /** The echoed scope filters. */
  "scope": Record<string, unknown>;
  "agentId": string;
  /** "all" when every class the agent touched is aggregated; otherwise the single class requested. */
  "taskClass": string;
  /** FR-M37-03: the weighted combination over the components with evidence (weights in the module docstring); null when no component has evidence — an empty sample is "insufficient evidence", never zero. */
  "score": number | null;
  /** ok: every component has evidence; partial: at least one does (the missing ones stay visible in components); insufficient_evidence: none does; insufficient_coverage (FR-M41-06): the population's attribution coverage fell below the configured floor — no score is shown. */
  "status": "ok" | "partial" | "insufficient_evidence" | "insufficient_coverage";
  /** The components WITH evidence that fed the score — a bad component is exposed in components, never hidden by the aggregate. */
  "coverage": string[];
  /** The full FR-M37-03 decomposition: firstPassYield, rejectionRate, calibrationError, postMergeRevertRate, incidentLinkage — each {status: ok|insufficient_evidence|unknown, value, sampleSize, ...}. */
  "components": Record<string, unknown>;
  /** AMD-M37 (G6): greenfield / brownfield / unclassified -> the same score shape per bucket (score, status, sampleSize, coverage, components). Buckets are decompositions of the headline figure, qualified by the headline's coverageEnvelope (including the FR-M41-06 floor). */
  "split": Record<string, unknown>;
  /** FR-M41-08: the coverage disclosure over the scanned diff population. Named coverageEnvelope (not coverage) because this result's `coverage` key already names the FR-M37-03 component list. */
  "coverageEnvelope": CoverageEnvelope;
  /** True when served from the in-process cache (FR-M17-05). */
  "cacheHit": boolean;
}

/** FR-M35-02 observation confidence: direct (the agent's own telemetry/ACP session), telemetry (evidence the agent left behind: git trailers, SCM/PR API, OS process listing), inferred (filesystem/git inference — the floor, never silence). */
export type ObservationConfidence = "direct" | "telemetry" | "inferred";

/** SEC-27: observer-facing APIs accept NO credential parameters — the observation surface is one-way. Empty params; additionalProperties false keeps it that way. */
export type ObserveSessionsParams = Record<string, never>;

/** X-29: one external agent session as shown in the Crown — vendor tag (FR-M35-03) + observation confidence (FR-M35-02), never indistinguishable from a Meridian-native pass. */
export interface ObserveSession {
  "sessionId": string;
  /** claude-code | copilot | cursor | codex | devin | gemini */
  "vendor": string;
  "confidence": ObservationConfidence;
  /** process | otel | git-trailers | scm-api | filesystem */
  "source": string;
  "detail": string;
  /** OS pid when detected by process inspection (X-29). */
  "pid"?: number | null;
  /** ISO 8601 UTC; null when unknown (process sessions). */
  "startedAt"?: string | null;
  "lastActivityAt"?: string | null;
  "agentId"?: string | null;
}

export interface ObserveSessionsResult {
  "sessions": ObserveSession[];
  /** Sticky NFR-32 degradation warnings visible in the UI. */
  "warnings": string[];
}

export type ObserveHealthParams = Record<string, never>;

/** FR-M35-08: one observer adapter's health — versioned against the vendor release. */
export interface ObserverHealth {
  "name": string;
  "vendor"?: string;
  /** degraded means an NFR-32 downgrade warning is active — observation continues at lower confidence, never silence. */
  "status": "ok" | "degraded";
  "detail": string;
  "vendorRelease"?: string;
  "adapterVersion"?: string;
  "warnings": string[];
}

export interface ObserveHealthResult {
  "observers": ObserverHealth[];
  /** True once the X-29 session monitor thread is polling. */
  "monitorRunning": boolean;
  /** FR-M44-13 / AC-47 (N1-T22): explicit evidence_expired markers, one per vendor evidence source whose documented retention window closed this session — a named coverage gap, never an absence of activity. */
  "evidenceExpired"?: EvidenceExpiredMarker[];
}

/** FR-M44-13 / AC-47: one closed vendor retention window, explicitly marked. The marker NAMES the window (windowLabel carries vendor, source and the day count) and stays visible for the rest of the session — the downgrade lands within one session and the gap is never presented as an absence of activity. */
export interface EvidenceExpiredMarker {
  "marker": "evidence_expired";
  "vendor": string;
  "source": string;
  "windowDays": number;
  "windowLabel": string;
  /** ISO 8601 UTC: when the vendor-side evidence was created. */
  "evidenceTime": string;
  /** ISO 8601 UTC: evidenceTime + the window — the moment capture became impossible. */
  "closedAt": string;
  "message": string;
}

/** FR-M44-12 / NFR-37 (N1-T21): one volatile-evidence capture. vendor/source select the documented retention window (FR-M44-11); evidenceTime is when the vendor-side evidence was created; capturedAt defaults to now; unavailable names what could not be captured at capture time. */
export interface CaptureEvidenceParams {
  /** The vendor whose evidence was captured (claude | copilot | cursor | codex | devin). */
  "vendor": string;
  /** The vendor evidence source (e.g. agent-session-logs); selects the documented retention window. */
  "source": string;
  /** ISO 8601 UTC: when the vendor-side evidence was created. */
  "evidenceTime": string;
  /** ISO 8601 UTC: when Meridian captured it; absent = now. */
  "capturedAt"?: string;
  /** What was unavailable at capture time (FR-M44-12) — recorded, never silently dropped. */
  "unavailable"?: string[];
}

export interface CaptureEvidenceResult {
  "recorded": boolean;
  /** The CaptureRecord: latency, window remaining, achieved margin, unavailable list, within-window flag. */
  "capture": Record<string, unknown>;
  /** The FR-M44-11 retention window record (citation + retrieved date); null when the vendor/source pair is not recorded. */
  "window": Record<string, unknown> | null;
  /** documented = a cited retention window exists; unknown = P26, no margin is claimed. */
  "windowStatus": "documented" | "unknown";
  /** NFR-37: the configured margin target (fraction of the window remaining at capture). */
  "marginTarget": number;
  /** NFR-37: captured with at least marginTarget of the window remaining; False when the window is unknown (reported, not assumed). */
  "meetsMarginTarget": boolean;
  /** FR-M44-13 / AC-47: every closed window marked so far this session, named — empty when nothing has expired. */
  "expired": EvidenceExpiredMarker[];
}

export interface TierSetParams {
  "tiers": TierName[];
}

